create or replace function public.cl_install_vendor(
  p_install_id text, p_phrase text, p_device_key text, p_create boolean,
  p_business_name text default null, p_device_code text default null)
returns public.cl_vendors
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype;
begin
  if p_install_id is null or length(trim(p_install_id)) = 0 then raise exception 'install_id is required'; end if;
  if cl_norm_phrase(p_phrase) = '' then raise exception 'shop_secret_phrase is required'; end if;

  select * into v from cl_vendors where install_id = p_install_id for update;
  if not found then
    if not p_create then raise exception 'This device is not registered yet' using errcode = 'P0002'; end if;
    insert into cl_vendors (business_name, install_id, device_code, shop_secret_phrase, device_key,
                            status, app_registered_at, last_checkin_at)
    values (coalesce(nullif(trim(coalesce(p_business_name,'')), ''), 'Unnamed vendor'), p_install_id,
            nullif(trim(coalesce(p_device_code,'')), ''), p_phrase, nullif(p_device_key, ''),
            'onboarding', now(), now())
    returning * into v;
    return v;
  end if;

  if v.shop_secret_phrase is not null and cl_norm_phrase(v.shop_secret_phrase) <> cl_norm_phrase(p_phrase) then
    raise exception 'Shop secret phrase does not match this install';
  end if;
  if v.device_key is not null and v.device_key is distinct from nullif(p_device_key, '') then
    raise exception 'This install ID is already registered to another device';
  end if;
  if v.device_key is null and nullif(p_device_key, '') is not null then
    update cl_vendors set device_key = p_device_key where id = v.id returning * into v;
  end if;
  return v;
end $fn$;

create or replace function public.cl_terminal_join(
  p_install_id text, p_secret_phrase text, p_device_key text, p_join_code text,
  p_label text default null, p_legacy_branch_id text default null,
  p_device_phrase text default null, p_device_code text default null, p_business_name text default null,
  p_expected_branch_name text default null, p_app_build integer default null)   -- admin passcode from main
returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; jc cl_branch_join_codes%rowtype; br cl_branches%rowtype; biz cl_businesses%rowtype;
        t cl_terminals%rowtype; norm text := cl_norm_join_code(p_join_code);
begin
  if (select count(*) from cl_join_failures where install_id = p_install_id and ts > now() - interval '1 hour') >= 10 then
    raise exception 'JOIN_LOCKED: Too many wrong codes. Try again in an hour.' using errcode = 'P0001';
  end if;

  select * into jc from cl_branch_join_codes where code_hash = encode(extensions.digest(norm, 'sha256'), 'hex') for update;
  if not found then
    insert into cl_join_failures (install_id) values (p_install_id);
    -- the failure row must survive the exception, so return an error object
    -- instead of raising (a raise would roll the insert back)
    return json_build_object('error', 'JOIN_CODE_INVALID');
  end if;
  select * into br from cl_branches where id = jc.branch_id;
  select * into biz from cl_businesses where id = br.business_id;

  if extensions.crypt(cl_norm_phrase(p_secret_phrase), biz.secret_phrase_hash) <> biz.secret_phrase_hash then
    insert into cl_join_failures (install_id) values (p_install_id);
    return json_build_object('error', 'PHRASE_MISMATCH');
  end if;

  -- Already a terminal? A retried join answers the same; nothing is created.
  select * into t from cl_terminals where install_id = p_install_id;
  if found then
    if not t.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;   -- Phase 2
    v := cl_install_vendor(p_install_id, coalesce(nullif(p_device_phrase, ''), p_secret_phrase), p_device_key, false);
    if t.branch_id = br.id then return cl_terminal_join_json(t.id, jc.id); end if;   -- admin passcode from main
    return json_build_object('error', 'ALREADY_JOINED', 'branch_id', t.branch_id);
  end if;
  -- Every refusal comes before anything is written for this install.
  if jc.used_by_terminal is not null then return json_build_object('error', 'JOIN_CODE_USED'); end if;
  if jc.expires_ts < now() then return json_build_object('error', 'JOIN_CODE_EXPIRED'); end if;
  -- admin passcode from main: an app before v21 would ignore the Admin passcode (and let anyone set one)
  if coalesce(p_app_build, 0) < 21 then
    raise exception 'APP_UPDATE_NEEDED: Update this app first, then join again. Your join code is still valid.' using errcode = 'P0001';
  end if;
  if jc.admin_check is null then return json_build_object('error', 'ADMIN_SEED_MISSING'); end if;   -- a code from an older main build
  -- An existing device's branch name is locked (DN keys carry it), so it
  -- may only join a branch of the same name.
  if nullif(btrim(coalesce(p_expected_branch_name,'')), '') is not null
     and cl_branch_key(p_expected_branch_name) <> cl_branch_key(br.name) then
    return json_build_object('error', 'BRANCH_NAME_MISMATCH', 'branch_name', br.name);
  end if;
  if exists (select 1 from cl_vendors where install_id = p_install_id and business_id is not null and business_id <> biz.id) then
    return json_build_object('error', 'OTHER_BUSINESS');
  end if;
  -- Price plans (20261013120000): a branch beyond the plan's limit (Lite: one) takes no tills.
  if not br.is_main and not cl_plan_branch_allowed(br.id, (cl_plan_version((select pl.plan_code from cl_plan_of(biz.id, null) pl))).max_branches) then
    raise exception '%', cl_plan_branch_limit_text((cl_plan_version((select pl.plan_code from cl_plan_of(biz.id, null) pl))).max_branches);
  end if;

  v := cl_install_vendor(p_install_id, coalesce(nullif(p_device_phrase, ''), p_secret_phrase), p_device_key, true,
                         coalesce(p_business_name, biz.name), p_device_code);

  perform 1 from cl_branches where id = br.id for update;            -- serialise till numbering
  insert into cl_terminals (business_id, branch_id, vendor_id, install_id, till_code, label, last_seen_ts)
  values (biz.id, br.id, v.id, v.install_id, cl_next_till_code(br.id), nullif(btrim(coalesce(p_label,'')), ''), now())
  returning * into t;
  update cl_branch_join_codes set used_by_terminal = t.id, used_ts = now() where id = jc.id;
  update cl_vendors set business_id = biz.id where id = v.id;
  if not br.is_main and br.legacy_branch_id is null and nullif(p_legacy_branch_id, '') is not null then
    update cl_branches set legacy_branch_id = p_legacy_branch_id where id = br.id;
  end if;
  return cl_terminal_join_json(t.id, jc.id);   -- admin passcode from main
end $fn$;

create or replace function public.cl_plan_price(p_vendor_id uuid, p_install_id text, p_days integer) returns jsonb
language plpgsql stable set search_path = public as $fn$
declare
  te cl_terminals%rowtype; br cl_branches%rowtype; v_biz uuid; v_role text; v_rank integer;
  v_plan record; v_ver cl_price_plan_versions%rowtype; v_byte smallint; v_fee numeric;
begin
  if p_days is null or p_days < 1 or p_days > 366 then raise exception 'Days must be 1..366'; end if;
  if nullif(p_install_id, '') is not null then
    select * into te from cl_terminals where install_id = upper(p_install_id);
  elsif p_vendor_id is not null then
    select * into te from cl_terminals where vendor_id = p_vendor_id;
  end if;
  if te.id is not null then
    if not te.active then
      raise exception 'TILL_INACTIVE: Till % of this business is deactivated. Reactivate it from a main-branch till first.', te.till_code;
    end if;
    select * into br from cl_branches where id = te.branch_id;
    select count(*) + 1 into v_rank from cl_terminals o
     where o.branch_id = te.branch_id and o.active and substr(o.till_code, 2)::int < substr(te.till_code, 2)::int;
    v_role := case when v_rank > 1 then 'till' when br.is_main then 'main' else 'branch' end;
    v_biz := te.business_id;
  else
    v_role := 'main';   -- a device that isn't a till of a business is its shop's main till
    v_biz := (select vd.business_id from cl_vendors vd where vd.id = p_vendor_id);
  end if;
  select * into v_plan from cl_plan_of(v_biz, p_vendor_id);
  v_ver := cl_plan_version(v_plan.plan_code);
  if v_ver.id is null then raise exception 'No price is in effect for plan %', v_plan.plan_code; end if;
  if br.id is not null and not br.is_main and not cl_plan_branch_allowed(br.id, v_ver.max_branches) then
    raise exception '%', cl_plan_branch_limit_text(v_ver.max_branches);
  end if;
  v_fee := case v_role when 'main' then v_ver.main_fee when 'branch' then v_ver.branch_fee else v_ver.till_fee end;
  if v_fee is null then raise exception '%', cl_plan_branch_limit_text(v_ver.max_branches); end if;
  select p.licence_byte into v_byte from cl_price_plans p where p.code = v_plan.plan_code;
  return jsonb_build_object('plan_code', v_plan.plan_code, 'plan_name', v_ver.name, 'plan_version_id', v_ver.id, 'plan_byte', v_byte,
    'plan_source', v_plan.plan_source, 'business_id', v_biz, 'terminal_id', te.id, 'till_code', te.till_code,
    'till_role', v_role, 'unit_fee', v_fee, 'days', p_days, 'amount', round(v_fee * p_days / 30.0, 2), 'currency', v_ver.currency);
end $fn$;

create or replace function public.cl_next_till_code(p_branch_id uuid) returns text
language sql volatile set search_path = public as $$
  select 'T' || (coalesce(max(substr(till_code, 2)::int), 0) + 1)::text from cl_terminals where branch_id = p_branch_id
$$;

create or replace function public.cl_licence_prepare(p_device_code text default null, p_business_id uuid default null,
                                          p_days integer default 30, p_plan integer default 0,
                                          p_key_id integer default 1, p_note text default null)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_staff uuid := cl_jwt_sub();
  v_from date := (now() at time zone 'Africa/Harare')::date;
  v_to date;
  t record;
  out_rows json[] := '{}';
  skipped json[] := '{}';
  v_install text; v_tag text; v_hash bytea; v_binding bytea; v_strong boolean;
  v_code text; v_payload bytea; v_serial integer; v_flags integer;
  v_biz_bytes bytea; v_vendor cl_vendors%rowtype;
  v_price jsonb;   -- Price plans (20261013120000)
begin
  if not cl_licence_staff_ok() then raise exception 'Not authorized' using errcode = '42501'; end if;
  if p_days not in (30, 90, 365) then raise exception 'Days must be 30, 90 or 365'; end if;
  if p_plan is null or p_plan < 0 or p_plan > 255 then raise exception 'Plan must be 0..255'; end if;
  if p_key_id is null or p_key_id < 1 or p_key_id > 255 then raise exception 'Key ID must be 1..255'; end if;
  if (p_device_code is null) = (p_business_id is null) then raise exception 'Give either a device code or a business'; end if;
  if p_device_code is not null and upper(regexp_replace(p_device_code, '\s', '', 'g')) !~ '^[A-Z0-9]{4,8}-[A-HJ-NP-Z2-9]{4}$' then
    raise exception 'Device code must look like ABCD-K7Q2 (install ID, dash, 4 characters)';
  end if;
  v_to := v_from + p_days;

  for t in
    select x.install_id, x.tag, x.vendor_id, x.business_id, x.terminal_id, x.till_code, x.branch_name, x.business_name
    from (
      -- one device, by the code on its screen
      select upper(split_part(regexp_replace(p_device_code, '\s', '', 'g'), '-', 1)) install_id,
             upper(split_part(regexp_replace(p_device_code, '\s', '', 'g'), '-', 2)) tag,
             vd.id vendor_id, te.business_id, te.id terminal_id, te.till_code, br.name branch_name, bz.name business_name
      from (select 1) one
      left join cl_vendors vd on vd.install_id = upper(split_part(regexp_replace(p_device_code, '\s', '', 'g'), '-', 1))
      left join cl_terminals te on te.install_id = vd.install_id
      left join cl_branches br on br.id = te.branch_id
      left join cl_businesses bz on bz.id = te.business_id
      where p_device_code is not null
      union all
      -- every active till of a business (the tag comes from the device key the server holds)
      select te.install_id, null, te.vendor_id, te.business_id, te.id, te.till_code, br.name, bz.name
      from cl_terminals te join cl_branches br on br.id = te.branch_id join cl_businesses bz on bz.id = te.business_id
      where p_business_id is not null and te.business_id = p_business_id and te.active
    ) x
    order by x.branch_name nulls first, x.till_code nulls first
  loop
    v_install := t.install_id;
    select * into v_vendor from cl_vendors where id = t.vendor_id;
    if v_install !~ '^[A-Z0-9]{4,8}$' then raise exception 'Device code must look like ABCD-K7Q2 (install ID, dash, 4 characters)'; end if;
    -- One issue per DEVICE per staff member per 30 seconds: a repeated tap or
    -- a retried request must not sign and charge twice. Other tills of the
    -- same business are not affected (T1, T2, T3 back to back is fine).
    perform pg_advisory_xact_lock(hashtext('cl_licence_prepare:' || v_install));
    select l.serial into v_serial from cl_licences l
     where l.issued_by = v_staff and l.install_id = v_install and l.issued_at > now() - interval '30 seconds'
     order by l.serial desc limit 1;
    if found then
      raise exception 'DUPLICATE_ISSUE: licence #% was issued for this device (%) a few seconds ago. Check the list; to issue another, wait 30 seconds.',
        v_serial, v_install;
    end if;
    if v_vendor.device_key is not null then
      v_hash := cl_licence_hash(v_vendor.device_key);
      v_tag := cl_licence_tag(v_hash);
      if t.tag is not null and t.tag <> v_tag then
        raise exception 'DEVICE_CODE_MISMATCH: % is not the code of install % (check the 4 characters after the dash)', p_device_code, v_install;
      end if;
      v_binding := substring(v_hash from 1 for 8);
      v_strong := true;
    elsif t.tag is not null then
      if t.tag !~ '^[A-HJ-NP-Z2-9]{4}$' then raise exception 'Device code must look like ABCD-K7Q2 (install ID, dash, 4 characters)'; end if;
      v_tag := t.tag;
      -- the tag's 20 bits, left-aligned in 3 bytes, then zeros
      v_flags := ((strpos('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', substr(v_tag,1,1)) - 1) << 15)
               | ((strpos('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', substr(v_tag,2,1)) - 1) << 10)
               | ((strpos('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', substr(v_tag,3,1)) - 1) << 5)
               |  (strpos('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', substr(v_tag,4,1)) - 1);
      v_binding := set_byte(set_byte(set_byte('\x0000000000000000'::bytea, 0, (v_flags >> 12) & 255), 1, (v_flags >> 4) & 255), 2, (v_flags & 15) << 4);
      v_strong := false;
    else
      skipped := skipped || json_build_object('till_code', t.till_code, 'branch', t.branch_name, 'install_id', v_install,
                                              'reason', 'NO_DEVICE_KEY');
      continue;
    end if;

    -- Price plans (20261013120000): this till's plan, role and price, worked
    -- out now and kept on the licence (the charge at attach uses exactly
    -- this). Refuses a deactivated till and a branch over the plan's limit.
    -- The payload's plan byte is the plan's (p_plan is no longer used).
    v_price := cl_plan_price(t.vendor_id, v_install, p_days);
    v_code := cl_licence_new_code();
    insert into cl_licences (key_id, install_id, device_tag, binding, strong_binding, vendor_id, business_id, terminal_id,
                             plan, days, valid_from, valid_to, payload, short_code_hash, note, issued_by,
                             price_plan_code, plan_version_id, plan_source, till_role, unit_fee, amount, currency)
    values (p_key_id, v_install, v_tag, v_binding, v_strong, t.vendor_id, t.business_id, t.terminal_id,
            (v_price->>'plan_byte')::smallint, p_days, v_from, v_to, '\x'::bytea, encode(extensions.digest(v_code, 'sha256'), 'hex'), p_note, v_staff,
            v_price->>'plan_code', (v_price->>'plan_version_id')::uuid, v_price->>'plan_source', v_price->>'till_role',
            (v_price->>'unit_fee')::numeric, (v_price->>'amount')::numeric, v_price->>'currency')
    returning serial into v_serial;

    -- payload (activation.js parseLicence): version, key, serial, install ID (8, NUL-padded),
    -- binding (8), issued day, valid-until day, plan, flags, features, [business ID]
    v_biz_bytes := case when t.business_id is null then '\x'::bytea else decode(replace(t.business_id::text, '-', ''), 'hex') end;
    v_flags := (case when v_strong then 1 else 0 end) | (case when t.business_id is null then 0 else 2 end);
    v_payload := set_byte('\x00'::bytea, 0, 2) || set_byte('\x00'::bytea, 0, p_key_id)
      || int4send(v_serial)
      || convert_to(v_install, 'UTF8') || substring('\x0000000000000000'::bytea from 1 for 8 - length(v_install))
      || v_binding
      || substring(int4send(v_from - date '2026-01-01') from 3 for 2)
      || substring(int4send(v_to - date '2026-01-01') from 3 for 2)
      || set_byte('\x00'::bytea, 0, (v_price->>'plan_byte')::int) || set_byte('\x00'::bytea, 0, v_flags)
      || '\x0000'::bytea
      || v_biz_bytes;
    update cl_licences set payload = v_payload where serial = v_serial;

    out_rows := out_rows || json_build_object('serial', v_serial, 'payload_hex', encode(v_payload, 'hex'),
      'short_code', substr(v_code,1,4) || '-' || substr(v_code,5,4) || '-' || substr(v_code,9,2),
      'device_code', v_install || '-' || v_tag, 'install_id', v_install, 'strong_binding', v_strong,
      'business_id', t.business_id, 'business_name', t.business_name, 'branch', t.branch_name, 'till_code', t.till_code,
      'valid_from', v_from, 'valid_to', v_to, 'days', p_days,
      'plan_code', v_price->>'plan_code', 'plan_name', v_price->>'plan_name', 'plan_source', v_price->>'plan_source',
      'till_role', v_price->>'till_role', 'unit_fee', v_price->'unit_fee', 'amount', v_price->'amount', 'currency', v_price->>'currency',
      'charged', t.vendor_id is not null);
  end loop;

  if p_device_code is not null and array_length(out_rows, 1) is null and array_length(skipped, 1) is null then
    raise exception 'Device code not recognised';
  end if;
  return json_build_object('licences', to_json(out_rows), 'skipped', to_json(skipped));
end $fn$;

create or replace function public.cl_trial_payload(p_serial integer) returns bytea
language plpgsql security definer set search_path = public as $fn$
declare l cl_licences%rowtype; v_biz bytea; v_flags integer; v_payload bytea;
begin
  select * into l from cl_licences where serial = p_serial and kind = 'trial' for update;
  if not found then raise exception 'No such trial licence'; end if;
  v_biz := case when l.business_id is null then '\x'::bytea else decode(replace(l.business_id::text, '-', ''), 'hex') end;
  v_flags := (case when l.strong_binding then 1 else 0 end) | (case when l.business_id is null then 0 else 2 end) | 4;
  v_payload := set_byte('\x00'::bytea, 0, 2) || set_byte('\x00'::bytea, 0, l.key_id)
    || int4send(l.serial)
    || convert_to(l.install_id, 'UTF8') || substring('\x0000000000000000'::bytea from 1 for 8 - length(l.install_id))
    || l.binding
    || substring(int4send(l.valid_from - date '2026-01-01') from 3 for 2)
    || substring(int4send(l.valid_to - date '2026-01-01') from 3 for 2)
    || set_byte('\x00'::bytea, 0, l.plan) || set_byte('\x00'::bytea, 0, v_flags)
    || '\x0000'::bytea
    || v_biz;
  update cl_licences set payload = v_payload where serial = p_serial;
  return v_payload;
end $fn$;

create or replace function public.cl_branch_list(p_install_id text, p_secret_phrase text, p_device_key text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; me cl_terminals%rowtype; caller_main boolean;
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  select * into me from cl_terminals where vendor_id = v.id and active;
  if not found then raise exception 'This device is not a registered terminal' using errcode = 'P0002'; end if;
  select is_main into caller_main from cl_branches where id = me.branch_id;
  return json_build_object(
    'business_id', me.business_id,
    'business_name', (select name from cl_businesses where id = me.business_id),
    'branches', coalesce((select json_agg(json_build_object(
        'id', b.id, 'name', b.name, 'is_main', b.is_main,
        'terminals', case when caller_main then coalesce((select json_agg(json_build_object(
            'id', t.id, 'till_code', t.till_code, 'label', t.label, 'active', t.active,
            'registered_ts', t.registered_ts, 'last_seen_ts', t.last_seen_ts) order by t.till_code)
          from cl_terminals t where t.branch_id = b.id), '[]'::json) else null end)
        order by b.is_main desc, b.name)
      from cl_branches b where b.business_id = me.business_id), '[]'::json));
end $fn$;

create or replace function public.cl_bs_enabled(p_business uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select (select count(*) from cl_terminals t where t.business_id = p_business and t.active) >= 2
$$;

create or replace function public.cl_stock_start_shared(p_install_id text, p_secret_phrase text, p_device_key text, p_op_id text, p_rows jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; b cl_branches%rowtype; r jsonb; v_p text; v_q integer; n integer := 0;
        old_till cl_terminals%rowtype;                                -- build guard
begin
  me := cl_catalogue_caller(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  if p_op_id is null or p_op_id !~ '^[0-9a-f]{32}$' then raise exception 'A start needs an operation id' using errcode = 'P0001'; end if;
  perform 1 from cl_businesses where id = me.business_id for update;
  select * into b from cl_branches where id = me.branch_id for update;
  if exists (select 1 from cl_stock_events where ref_uid = 'start:'||p_op_id) then
    return json_build_object('stock_mode', 'shared', 'already', true);
  end if;
  if b.stock_mode = 'shared' then return json_build_object('error', 'ALREADY_SHARED'); end if;
  if cl_stock_holder(b.id) <> me.id then return json_build_object('error', 'NOT_HOLDER'); end if;
  if cl_stock_active_tills(b.id) < 2 then return json_build_object('error', 'SINGLE_TILL'); end if;
  -- build guard: every other active till must have reported build 7 or later
  select * into old_till from cl_terminals
   where branch_id = b.id and active and id <> me.id and coalesce(app_build, 0) < 7
   order by till_code, id limit 1;
  if found then
    return json_build_object('error', 'TILL_NEEDS_UPDATE', 'till_code', old_till.till_code, 'label', old_till.label,
                             'app_build', old_till.app_build, 'min_build', 7);
  end if;
  -- end build guard
  if (case when jsonb_typeof(p_rows) = 'array' then jsonb_array_length(p_rows) > 20000 else true end) then
    raise exception 'Send the stock as a list of at most 20000 products' using errcode = 'P0001';
  end if;
  for r in select value from jsonb_array_elements(p_rows) loop
    v_p := r->>'product_uid'; v_q := (r->>'qty')::integer;
    if v_q is null or v_q < 0 then raise exception 'Stock for % must be zero or more', v_p using errcode = 'P0001'; end if;
    if not exists (select 1 from cl_catalogue_products where business_id = me.business_id and product_uid = v_p) then
      raise exception 'Product % is not in the catalogue', v_p using errcode = 'P0001';
    end if;
    perform cl_stock_add(me.business_id, b.id, v_p, v_q);
    perform cl_stock_event('start:'||p_op_id||':'||v_p, 'start:'||p_op_id, me.business_id, b.id, me.id, v_p, 'opening', v_q, 0, 0, '{}'::jsonb);
    n := n + 1;
  end loop;
  update cl_branches set stock_mode = 'shared', stock_shared_ts = now() where id = b.id;
  insert into cl_till_stock_state (terminal_id, branch_id, last_sync_ts) values (me.id, b.id, now())
  on conflict (terminal_id) do update set last_sync_ts = now();
  perform cl_stock_check(b.id);
  return json_build_object('stock_mode', 'shared', 'products', n);
end $fn$;

create or replace function public.cl_device_grv_post(p_install_id text, p_secret_phrase text, p_device_key text, p_dispatch_id uuid, p_grv jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; d cl_dispatches%rowtype; v_grv uuid; l record; g jsonb; v_r integer; v_dm integer; v_x integer;
        v_diff boolean := false; v_status text;
begin
  me := cl_dispatch_caller(p_install_id, p_secret_phrase, p_device_key);
  select * into d from cl_dispatches where id = p_dispatch_id for update;
  if not found or d.business_id <> me.business_id then return json_build_object('error', 'NO_SUCH_DISPATCH', 'message', 'That dispatch isn''t on the server.'); end if;
  if d.to_branch_id <> me.branch_id then return json_build_object('error', 'NOT_YOUR_BRANCH', 'message', 'This dispatch is for ' || (select name from cl_branches where id = d.to_branch_id) || ', not this branch.'); end if;
  begin v_grv := (p_grv->>'grv_id')::uuid; exception when others then v_grv := null; end;
  if v_grv is null then raise exception 'The GRV needs its id' using errcode = 'P0001'; end if;
  if d.grv_id = v_grv then return json_build_object('ok', true, 'already', true, 'dispatch', cl_dispatch_json(d.id)); end if;
  if d.status = 'cancelled' then
    return json_build_object('error', 'CANCELLED', 'message', d.dn_display || ' was cancelled by ' || (select name from cl_branches where id = d.from_branch_id) || '. Nothing was received.');
  end if;
  if d.grv_id is not null then
    return json_build_object('error', 'ALREADY_RECEIVED', 'grv_display', d.grv_display,
      'message', d.dn_display || ' was already received as ' || d.grv_display || ' on till ' || coalesce((select till_code from cl_terminals where id = d.grv_terminal_id), '?')
                 || coalesce(' by ' || d.grv_by, '') || '. Nothing was added here.');
  end if;
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE', 'message', 'This till is switched off for the business. Ask the main branch.'); end if;
  if coalesce(p_grv->>'grv_no', '') !~ '^[0-9]{1,9}$' or (p_grv->>'grv_no')::integer < 1 then raise exception 'The GRV needs its number' using errcode = 'P0001'; end if;
  if jsonb_typeof(p_grv->'lines') is distinct from 'array'
     or jsonb_array_length(p_grv->'lines') <> (select count(*) from cl_dispatch_lines where dispatch_id = d.id)
     or (select count(distinct x->>'line_no') from jsonb_array_elements(p_grv->'lines') x) <> jsonb_array_length(p_grv->'lines') then
    raise exception 'Count every line of the dispatch once' using errcode = 'P0001';
  end if;

  for l in select * from cl_dispatch_lines where dispatch_id = d.id order by line_no for update loop
    select x into g from jsonb_array_elements(p_grv->'lines') x where (x->>'line_no') = l.line_no::text;
    if g is null then raise exception 'Count every line of the dispatch once (line % is missing)', l.line_no using errcode = 'P0001'; end if;
    if coalesce(g->>'received', '') !~ '^[0-9]{1,7}$' or coalesce(g->>'damaged', '0') !~ '^[0-9]{1,7}$' or coalesce(g->>'extra', '0') !~ '^[0-9]{1,7}$' then
      raise exception '%: the counts must be whole numbers of 0 or more', l.name using errcode = 'P0001';
    end if;
    v_r := (g->>'received')::integer; v_dm := coalesce((g->>'damaged')::integer, 0); v_x := coalesce((g->>'extra')::integer, 0);
    if v_r + v_dm > l.qty then raise exception '%: received and damaged add up to more than the % sent; count the rest as extra', l.name, l.qty using errcode = 'P0001'; end if;
    if v_x > 0 and v_r + v_dm < l.qty then raise exception '%: extra only when the full % sent arrived', l.name, l.qty using errcode = 'P0001'; end if;
    update cl_dispatch_lines set received = v_r, damaged = v_dm, short = l.qty - v_r - v_dm, extra = v_x, note = cl_dispatch_name(g->>'note', 200)
     where dispatch_id = d.id and line_no = l.line_no;
    if l.qty - v_r - v_dm > 0 then insert into cl_dispatch_issues (dispatch_id, line_no, kind, qty) values (d.id, l.line_no, 'short', l.qty - v_r - v_dm); v_diff := true; end if;
    if v_dm > 0 then insert into cl_dispatch_issues (dispatch_id, line_no, kind, qty) values (d.id, l.line_no, 'damaged', v_dm); v_diff := true; end if;
    if v_x > 0 then insert into cl_dispatch_issues (dispatch_id, line_no, kind, qty) values (d.id, l.line_no, 'extra', v_x); v_diff := true; end if;
  end loop;

  v_status := case when v_diff then 'received_diff' else 'received' end;
  update cl_dispatches set status = v_status, grv_id = v_grv, grv_no = (p_grv->>'grv_no')::integer,
         grv_display = coalesce(cl_dispatch_name(p_grv->>'grv_display', 40), 'GRV-' || (p_grv->>'grv_no')), grv_terminal_id = me.id,
         grv_by = cl_dispatch_name(p_grv->>'by', 80), grv_internal_ref = cl_dispatch_name(p_grv->>'internal_ref', 60),
         grv_note = cl_dispatch_name(p_grv->>'note', 200), received_at = now()
   where id = d.id;
  if d.delivery_cost > 0 then
    insert into cl_interbranch_charges (business_id, dispatch_id, owed_by_branch_id, owed_to_branch_id, amount, currency)
    values (d.business_id, d.id, d.to_branch_id, d.from_branch_id, d.delivery_cost, d.delivery_currency);
  end if;
  perform cl_dispatch_log_add(d.id, me.id, p_grv->>'by', 'received', jsonb_build_object('grv_id', v_grv, 'status', v_status,
    'via_file', coalesce((p_grv->>'via_file')::boolean, false)));
  return json_build_object('ok', true, 'dispatch', cl_dispatch_json(d.id));
exception when unique_violation then
  return json_build_object('error', 'GRV_NUMBER_USED', 'message', 'This till already used that GRV number. Check the date and time on this device, and its backups.');
end $fn$;

create or replace function public.cl_device_dispatch_send(p_install_id text, p_secret_phrase text, p_device_key text, p_dispatch jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; d cl_dispatches%rowtype; v_id uuid; v_to cl_branches%rowtype; l jsonb; n integer := 0;
        v_cost numeric; v_cur text; v_issue cl_dispatch_issues%rowtype; v_idata cl_dispatches%rowtype; v_ucost numeric;
begin
  me := cl_dispatch_caller(p_install_id, p_secret_phrase, p_device_key);
  if jsonb_typeof(p_dispatch) is distinct from 'object' then raise exception 'Send the dispatch as an object' using errcode = 'P0001'; end if;
  begin v_id := (p_dispatch->>'id')::uuid; exception when others then v_id := null; end;
  if v_id is null then raise exception 'The dispatch needs its id' using errcode = 'P0001'; end if;

  select * into d from cl_dispatches where id = v_id;
  if found then
    if d.from_terminal_id <> me.id then raise exception 'That dispatch id belongs to another till' using errcode = 'P0001'; end if;
    return json_build_object('ok', true, 'already', true, 'id', d.id, 'status', d.status);
  end if;
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE', 'message', 'This till is switched off for the business. Ask the main branch.'); end if;

  begin select * into v_to from cl_branches where id = (p_dispatch->>'to_branch_id')::uuid; exception when others then v_to := null; end;
  if v_to.id is null or v_to.business_id <> me.business_id then
    return json_build_object('error', 'NOT_OWN_BUSINESS', 'message', 'You can only dispatch to branches of your own business. Ask that branch to join with a join code.');
  end if;
  if v_to.id = me.branch_id then return json_build_object('error', 'OWN_BRANCH', 'message', 'You can''t dispatch to your own branch.'); end if;

  if (p_dispatch->>'dn_no') !~ '^[0-9]{1,9}$' or (p_dispatch->>'dn_no')::integer < 1 then raise exception 'The dispatch needs its DN number' using errcode = 'P0001'; end if;
  if exists (select 1 from cl_dispatches where from_terminal_id = me.id and dn_no = (p_dispatch->>'dn_no')::integer) then
    return json_build_object('error', 'DN_NUMBER_USED', 'message', 'This till already sent ' || (p_dispatch->>'dn_display') || ' as another dispatch. Check the date and time on this device, and its backups.');
  end if;
  if jsonb_typeof(p_dispatch->'lines') is distinct from 'array' or jsonb_array_length(p_dispatch->'lines') not between 1 and 500 then
    raise exception 'Send between 1 and 500 lines' using errcode = 'P0001';
  end if;

  v_cost := coalesce(nullif(p_dispatch->'delivery'->>'cost', '')::numeric, 0);
  v_cur := upper(nullif(btrim(coalesce(p_dispatch->'delivery'->>'currency', '')), ''));
  if v_cost < 0 or v_cost > 10000000 then raise exception 'The delivery cost must be between 0 and 10 000 000' using errcode = 'P0001'; end if;
  if v_cost > 0 and (v_cur is null or v_cur !~ '^[A-Z]{3}$') then raise exception 'The delivery cost needs its currency (3 letters, e.g. USD)' using errcode = 'P0001'; end if;

  if nullif(p_dispatch->>'replaces_issue_id', '') is not null then
    select i.* into v_issue from cl_dispatch_issues i where i.id = (p_dispatch->>'replaces_issue_id')::uuid for update;
    if not found then return json_build_object('error', 'NO_SUCH_ISSUE', 'message', 'That shortage isn''t on the server.'); end if;
    select * into v_idata from cl_dispatches where id = v_issue.dispatch_id;
    if v_idata.from_terminal_id <> me.id then return json_build_object('error', 'NOT_SENDER', 'message', 'Only the till that dispatched it (' || (select till_code from cl_terminals where id = v_idata.from_terminal_id) || ') can re-dispatch it.'); end if;
    if v_issue.kind not in ('short', 'damaged') or v_issue.status <> 'open' then
      return json_build_object('error', 'ALREADY_RESOLVED', 'message', 'That difference is already ' || replace(v_issue.status, '_', ' ') || '.');
    end if;
  end if;

  insert into cl_dispatches (id, business_id, from_branch_id, to_branch_id, from_terminal_id, from_legacy_branch_id, dn_no, dn_display, created_iso,
                             internal_ref, sent_by, delivery_cost, delivery_currency, carrier, delivery_ref, replaces_issue_id)
  values (v_id, me.business_id, me.branch_id, v_to.id, me.id, cl_dispatch_name(p_dispatch->>'from_legacy_branch_id', 40), (p_dispatch->>'dn_no')::integer,
          coalesce(cl_dispatch_name(p_dispatch->>'dn_display', 40), 'DN-' || (p_dispatch->>'dn_no')), cl_dispatch_name(p_dispatch->>'created_iso', 40),
          cl_dispatch_name(p_dispatch->>'internal_ref', 60), cl_dispatch_name(p_dispatch->>'sent_by', 80), v_cost, case when v_cost > 0 then v_cur end,
          cl_dispatch_name(p_dispatch->'delivery'->>'carrier', 80), cl_dispatch_name(p_dispatch->'delivery'->>'ref', 80), v_issue.id);

  for l in select value from jsonb_array_elements(p_dispatch->'lines') loop
    n := n + 1;
    if coalesce(l->>'qty', '') !~ '^[0-9]{1,7}$' or (l->>'qty')::integer not between 1 and 1000000 then
      raise exception 'Line %: the quantity must be a whole number of 1 or more', n using errcode = 'P0001';
    end if;
    if cl_dispatch_name(l->>'name', 120) is null then raise exception 'Line %: the product name is missing', n using errcode = 'P0001'; end if;
    v_ucost := nullif(l->>'unit_cost', '')::numeric;
    if v_ucost is not null and (v_ucost < 0 or v_ucost > 100000000) then raise exception 'Line %: the unit cost is out of range', n using errcode = 'P0001'; end if;
    insert into cl_dispatch_lines (dispatch_id, line_no, cat_uid, code, name, unit, qty, unit_cost)
    values (v_id, n, cl_dispatch_name(l->>'cat_uid', 64), cl_dispatch_name(l->>'code', 64), cl_dispatch_name(l->>'name', 120),
            cl_dispatch_name(l->>'unit', 20), (l->>'qty')::integer, v_ucost);
  end loop;

  if v_issue.id is not null then
    update cl_dispatch_issues set status = 'redispatched', resolved_at = now(), resolved_by = cl_dispatch_name(p_dispatch->>'sent_by', 80),
           resolved_terminal_id = me.id, redispatch_id = v_id, resolution_note = 'Re-dispatched as ' || (p_dispatch->>'dn_display')
     where id = v_issue.id;
    perform cl_dispatch_log_add(v_issue.dispatch_id, me.id, p_dispatch->>'sent_by', 'issue_redispatched', jsonb_build_object('issue_id', v_issue.id, 'dispatch_id', v_id));
  end if;
  perform cl_dispatch_log_add(v_id, me.id, p_dispatch->>'sent_by', 'sent', jsonb_build_object('lines', n, 'delivery_cost', v_cost));
  return json_build_object('ok', true, 'id', v_id, 'status', 'sent');
exception when unique_violation then
  return json_build_object('error', 'DN_NUMBER_USED', 'message', 'This till already sent that DN number as another dispatch.');
end $fn$;

create or replace function public.cl_device_dispatch_cancel(p_install_id text, p_secret_phrase text, p_device_key text, p_dispatch_id uuid, p_reason text, p_by text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; d cl_dispatches%rowtype; v_reason text := btrim(coalesce(p_reason, ''));
begin
  me := cl_dispatch_caller(p_install_id, p_secret_phrase, p_device_key);
  select * into d from cl_dispatches where id = p_dispatch_id for update;
  if not found or d.business_id <> me.business_id then return json_build_object('error', 'NO_SUCH_DISPATCH', 'message', 'That dispatch isn''t on the server.'); end if;
  if d.from_terminal_id <> me.id then
    return json_build_object('error', 'NOT_SENDER', 'message', 'Only the till that dispatched it (' || (select till_code from cl_terminals where id = d.from_terminal_id) || ') can cancel it.');
  end if;
  if d.status = 'cancelled' then return json_build_object('ok', true, 'already', true, 'dispatch', cl_dispatch_json(d.id)); end if;
  if d.grv_id is not null then
    return json_build_object('error', 'ALREADY_RECEIVED', 'grv_display', d.grv_display,
      'message', 'Already received as ' || d.grv_display || '. It can''t be cancelled now: send the goods back with a return dispatch.');
  end if;
  if length(v_reason) < 3 or length(v_reason) > 200 then raise exception 'Give a reason (3 to 200 characters)' using errcode = 'P0001'; end if;
  update cl_dispatches set status = 'cancelled', cancelled_at = now(), cancelled_by = cl_dispatch_name(p_by, 80), cancel_reason = v_reason where id = d.id;
  -- a cancelled re-dispatch opens its shortage again
  if d.replaces_issue_id is not null then
    update cl_dispatch_issues set status = 'open', resolved_at = null, resolved_by = null, resolved_terminal_id = null, redispatch_id = null, resolution_note = null
     where id = d.replaces_issue_id and redispatch_id = d.id;
    if found then
      perform cl_dispatch_log_add((select dispatch_id from cl_dispatch_issues where id = d.replaces_issue_id), me.id, p_by, 'issue_reopened',
        jsonb_build_object('issue_id', d.replaces_issue_id, 'cancelled_dispatch_id', d.id));
    end if;
  end if;
  perform cl_dispatch_log_add(d.id, me.id, p_by, 'cancelled', jsonb_build_object('reason', v_reason));
  return json_build_object('ok', true, 'dispatch', cl_dispatch_json(d.id));
end $fn$;

create or replace function public.cl_device_dispatch_resolve(p_install_id text, p_secret_phrase text, p_device_key text, p_issue_id uuid,
                                                  p_action text, p_by text, p_note text, p_adj_display text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; i cl_dispatch_issues%rowtype; d cl_dispatches%rowtype; v_to text;
begin
  me := cl_dispatch_caller(p_install_id, p_secret_phrase, p_device_key);
  select * into i from cl_dispatch_issues where id = p_issue_id for update;
  if found then select * into d from cl_dispatches where id = i.dispatch_id; end if;
  if i.id is null or d.business_id <> me.business_id then return json_build_object('error', 'NO_SUCH_ISSUE', 'message', 'That difference isn''t on the server.'); end if;
  if d.from_terminal_id <> me.id then
    return json_build_object('error', 'NOT_SENDER', 'message', 'Only the till that dispatched it (' || (select till_code from cl_terminals where id = d.from_terminal_id) || ') can resolve it.');
  end if;
  v_to := case p_action when 'write_off' then 'written_off' when 'confirm' then 'confirmed' when 'dispute' then 'disputed' end;
  if v_to is null or (p_action = 'write_off' and i.kind = 'extra') or (p_action in ('confirm', 'dispute') and i.kind <> 'extra') then
    raise exception 'That action doesn''t fit a % difference', i.kind using errcode = 'P0001';
  end if;
  if i.status = v_to then return json_build_object('ok', true, 'already', true, 'dispatch', cl_dispatch_json(d.id)); end if;
  if not (i.status = 'open' or (i.status = 'disputed' and p_action = 'confirm')) then
    return json_build_object('error', 'ALREADY_RESOLVED', 'message', 'That difference is already ' || replace(i.status, '_', ' ') || '.');
  end if;
  if p_action = 'write_off' and cl_dispatch_name(p_adj_display, 40) is null then raise exception 'A write-off needs its ADJ number' using errcode = 'P0001'; end if;
  if p_action in ('write_off', 'dispute') and length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'Give a reason (at least 3 characters)' using errcode = 'P0001'; end if;
  update cl_dispatch_issues set status = v_to, resolved_at = now(), resolved_by = cl_dispatch_name(p_by, 80), resolved_terminal_id = me.id,
         resolution_note = cl_dispatch_name(p_note, 200), adj_display = case when p_action = 'write_off' then cl_dispatch_name(p_adj_display, 40) end
   where id = i.id;
  perform cl_dispatch_log_add(d.id, me.id, p_by, 'issue_' || v_to, jsonb_build_object('issue_id', i.id, 'kind', i.kind, 'qty', i.qty, 'adj', p_adj_display));
  return json_build_object('ok', true, 'dispatch', cl_dispatch_json(d.id));
end $fn$;

create or replace function public.cl_device_supplier_grv_post(p_install_id text, p_secret_phrase text, p_device_key text, p_grv jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; v_id uuid; g cl_supplier_grvs%rowtype; s cl_suppliers%rowtype; l jsonb; n integer := 0;
        v_cost numeric; v_cur text; v_key text;
begin
  me := cl_dispatch_caller(p_install_id, p_secret_phrase, p_device_key);
  begin v_id := (p_grv->>'id')::uuid; exception when others then v_id := null; end;
  if v_id is null then raise exception 'The GRV needs its id' using errcode = 'P0001'; end if;
  select * into g from cl_supplier_grvs where id = v_id;
  if found then
    if g.terminal_id <> me.id then raise exception 'That GRV id belongs to another till' using errcode = 'P0001'; end if;
    return json_build_object('ok', true, 'already', true, 'grv', cl_supplier_grv_json(v_id));
  end if;
  me := cl_supplier_till(p_install_id, p_secret_phrase, p_device_key);
  if me.id is null then return json_build_object('error', 'MAIN_ONLY', 'message', 'Goods from suppliers are received on the main branch.'); end if;
  begin select * into s from cl_suppliers where id = (p_grv->>'supplier_id')::uuid; exception when others then s := null; end;
  if s.id is null or s.business_id <> me.business_id then return json_build_object('error', 'NO_SUCH_SUPPLIER', 'message', 'That supplier isn''t in the business''s list yet.'); end if;
  v_key := cl_invoice_key(p_grv->>'invoice_no');
  if v_key = '' or length(btrim(p_grv->>'invoice_no')) > 40 then raise exception 'Give the supplier''s invoice number' using errcode = 'P0001'; end if;
  select * into g from cl_supplier_grvs where business_id = me.business_id and supplier_id = s.id and invoice_key = v_key;
  if found then
    return json_build_object('error', 'DUPLICATE_INVOICE', 'grv_display', g.grv_display,
      'message', 'Invoice ' || g.invoice_no || ' from ' || s.name || ' was already received as ' || g.grv_display || ' on ' || to_char(g.posted_at at time zone 'Africa/Harare', 'DD Mon YYYY') || '. Nothing was added.');
  end if;
  if coalesce(p_grv->>'grv_no', '') !~ '^[0-9]{1,9}$' or (p_grv->>'grv_no')::integer < 1 then raise exception 'The GRV needs its number' using errcode = 'P0001'; end if;
  if jsonb_typeof(p_grv->'lines') is distinct from 'array' or jsonb_array_length(p_grv->'lines') not between 1 and 500 then
    raise exception 'Send between 1 and 500 lines' using errcode = 'P0001';
  end if;
  v_cost := coalesce(nullif(p_grv->'delivery'->>'cost', '')::numeric, 0);
  v_cur := upper(nullif(btrim(coalesce(p_grv->'delivery'->>'currency', '')), ''));
  if v_cost < 0 or v_cost > 10000000 then raise exception 'The delivery cost must be between 0 and 10 000 000' using errcode = 'P0001'; end if;
  if v_cost > 0 and (v_cur is null or v_cur !~ '^[A-Z]{3}$') then raise exception 'The delivery cost needs its currency (3 letters, e.g. USD)' using errcode = 'P0001'; end if;

  insert into cl_supplier_grvs (id, business_id, branch_id, terminal_id, supplier_id, invoice_no, invoice_key, grv_no, grv_display, received_by,
                                delivery_cost, delivery_currency, note, created_iso)
  values (v_id, me.business_id, me.branch_id, me.id, s.id, btrim(p_grv->>'invoice_no'), v_key, (p_grv->>'grv_no')::integer,
          coalesce(cl_dispatch_name(p_grv->>'grv_display', 40), 'GRV-' || (p_grv->>'grv_no')), cl_dispatch_name(p_grv->>'received_by', 80),
          v_cost, case when v_cost > 0 then v_cur end, cl_dispatch_name(p_grv->>'note', 200), cl_dispatch_name(p_grv->>'created_iso', 40));
  for l in select value from jsonb_array_elements(p_grv->'lines') loop
    n := n + 1;
    if coalesce(l->>'qty', '') !~ '^[0-9]{1,7}$' or (l->>'qty')::integer not between 1 and 1000000 then
      raise exception 'Line %: the quantity must be a whole number of 1 or more', n using errcode = 'P0001';
    end if;
    if cl_dispatch_name(l->>'name', 120) is null then raise exception 'Line %: the product name is missing', n using errcode = 'P0001'; end if;
    if nullif(l->>'unit_cost', '') is null or (l->>'unit_cost')::numeric < 0 then raise exception 'Line %: give the unit cost (0 or more)', n using errcode = 'P0001'; end if;
    insert into cl_supplier_grv_lines (grv_id, line_no, cat_uid, code, name, qty, unit_cost, landed_cost, old_price, new_price, price_by)
    values (v_id, n, cl_dispatch_name(l->>'cat_uid', 64), cl_dispatch_name(l->>'code', 64), cl_dispatch_name(l->>'name', 120), (l->>'qty')::integer,
            (l->>'unit_cost')::numeric, nullif(l->>'landed_cost', '')::numeric, nullif(l->>'old_price', '')::numeric, nullif(l->>'new_price', '')::numeric,
            case when nullif(l->>'new_price', '') is not null then cl_dispatch_name(l->>'price_by', 80) end);
  end loop;
  return json_build_object('ok', true, 'grv', cl_supplier_grv_json(v_id));
exception when unique_violation then
  if exists (select 1 from cl_supplier_grvs where business_id = me.business_id and supplier_id = s.id and invoice_key = v_key) then
    return json_build_object('error', 'DUPLICATE_INVOICE', 'message', 'Invoice ' || btrim(p_grv->>'invoice_no') || ' from ' || s.name || ' was just received on another till. Nothing was added.');
  end if;
  return json_build_object('error', 'GRV_NUMBER_USED', 'message', 'This till already used that GRV number. Check the date and time on this device, and its backups.');
end $fn$;

create or replace function public.cl_device_supplier_save(p_install_id text, p_secret_phrase text, p_device_key text, p_supplier jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; v_id uuid; v_name text := btrim(coalesce(p_supplier->>'name', '')); s cl_suppliers%rowtype;
begin
  me := cl_supplier_till(p_install_id, p_secret_phrase, p_device_key);
  if me.id is null then return json_build_object('error', 'MAIN_ONLY', 'message', 'Suppliers are kept on the main branch.'); end if;
  begin v_id := (p_supplier->>'id')::uuid; exception when others then v_id := null; end;
  if v_id is null then raise exception 'The supplier needs its id' using errcode = 'P0001'; end if;
  if length(v_name) not between 1 and 80 then raise exception 'Give the supplier''s name (up to 80 characters)' using errcode = 'P0001'; end if;
  select * into s from cl_suppliers where business_id = me.business_id and lower(btrim(name)) = lower(v_name) and id <> v_id;
  if found then return json_build_object('error', 'DUPLICATE_SUPPLIER', 'message', '"' || s.name || '" is already in the supplier list.', 'supplier', cl_supplier_json(s)); end if;
  select * into s from cl_suppliers where id = v_id;
  if found and s.business_id <> me.business_id then raise exception 'That supplier id belongs to another business' using errcode = 'P0001'; end if;
  insert into cl_suppliers (id, business_id, name, phone, notes, active, created_terminal)
  values (v_id, me.business_id, v_name, nullif(btrim(coalesce(p_supplier->>'phone', '')), ''), nullif(btrim(coalesce(p_supplier->>'notes', '')), ''),
          coalesce((p_supplier->>'active')::boolean, true), me.id)
  on conflict (id) do update set name = excluded.name, phone = excluded.phone, notes = excluded.notes, active = excluded.active, updated_at = now()
  returning * into s;
  return json_build_object('ok', true, 'supplier', cl_supplier_json(s));
end $fn$;

create or replace function public.cl_catalogue_push(p_install_id text, p_secret_phrase text, p_device_key text, p_rows jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; r jsonb; cur cl_catalogue_products%rowtype; had boolean;
        out_rows jsonb := '[]'::jsonb; s bigint; v_uid text; v_op text; v_code text; v_name text; v_active boolean;
        v_hash text; v_img text; v_price numeric; v_cost numeric; v_low integer; v_base bigint; v_bytes integer;
        v_wholesale numeric;   -- POS fixes (20261018180000)
begin
  me := cl_catalogue_caller(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  if not (select is_main from cl_branches where id = me.branch_id) then return json_build_object('error', 'NOT_MAIN'); end if;
  if (case when jsonb_typeof(p_rows) = 'array' then jsonb_array_length(p_rows) not between 1 and 100 else true end) then
    raise exception 'Send between 1 and 100 products at a time' using errcode = 'P0001';
  end if;
  perform 1 from cl_businesses where id = me.business_id for update;            -- orders change_seq within the business

  for r in select value from jsonb_array_elements(p_rows) loop
    v_uid := r->>'uid'; v_op := r->>'op_id';
    begin
      if v_uid is null or v_uid !~ '^[0-9a-f]{32}$' or v_op is null or v_op !~ '^[0-9a-f]{32}$' then
        out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'refused', 'reason', 'BAD_ROW'); continue;
      end if;
      select * into cur from cl_catalogue_products where business_id = me.business_id and product_uid = v_uid for update;
      had := found;
      if had and cur.last_op_id = v_op then
        out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'duplicate', 'seq', cur.change_seq); continue;
      end if;
      v_code := btrim(coalesce(r->>'code', '')); v_name := btrim(coalesce(r->>'name', ''));
      v_active := coalesce((r->>'active')::boolean, true);
      v_price := (r->>'price')::numeric; v_cost := coalesce((r->>'cost')::numeric, 0);
      v_low := coalesce((r->>'low_threshold')::integer, 5);
      v_hash := nullif(r->>'image_hash', ''); v_img := r->>'image'; v_base := (r->>'base_seq')::bigint;
      -- POS fixes (20261018180000): no key = keep what's stored; null = none
      v_wholesale := case when r ? 'wholesale_price' then (r->>'wholesale_price')::numeric else cur.wholesale_price end;
      if v_name = '' or v_price is null then
        out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'refused', 'reason', 'BAD_ROW'); continue;
      end if;
      if v_active and v_code <> '' and exists (select 1 from cl_catalogue_products
          where business_id = me.business_id and active and lower(btrim(code)) = lower(v_code) and product_uid <> v_uid) then
        out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'refused', 'reason', 'DUPLICATE_CODE'); continue;
      end if;
      -- picture: the till sends the data only when the server may not have it
      if v_hash is not null and v_img is not null then
        if encode(extensions.digest(v_img, 'sha256'), 'hex') <> v_hash then
          out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'refused', 'reason', 'BAD_IMAGE'); continue;
        end if;
      elsif v_hash is not null and not exists (select 1 from cl_catalogue_images
          where business_id = me.business_id and product_uid = v_uid and image_hash = v_hash) then
        out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'refused', 'reason', 'NEED_IMAGE'); continue;
      end if;
      v_bytes := case when v_hash is null then 0 when v_img is not null then length(v_img) else coalesce(cur.image_bytes, 0) end;

      s := nextval('cl_catalogue_seq');
      insert into cl_catalogue_products as c (business_id, product_uid, code, name, description, category, shelf, price, cost,
                                              low_threshold, active, image_hash, image_bytes, change_seq, last_op_id, updated_by, updated_ts,
                                              wholesale_price)   -- POS fixes (20261018180000)
      values (me.business_id, v_uid, v_code, v_name, coalesce(r->>'description', ''), coalesce(r->>'category', ''),
              coalesce(r->>'shelf', ''), v_price, v_cost, v_low, v_active, v_hash, v_bytes, s, v_op, me.id, now(),
              v_wholesale)   -- POS fixes (20261018180000)
      on conflict (business_id, product_uid) do update set
        code = excluded.code, name = excluded.name, description = excluded.description, category = excluded.category,
        shelf = excluded.shelf, price = excluded.price, cost = excluded.cost, low_threshold = excluded.low_threshold,
        active = excluded.active, image_hash = excluded.image_hash, image_bytes = excluded.image_bytes,
        change_seq = excluded.change_seq, last_op_id = excluded.last_op_id, updated_by = excluded.updated_by, updated_ts = now(),
        wholesale_price = excluded.wholesale_price;   -- POS fixes (20261018180000)
      if v_hash is null then
        delete from cl_catalogue_images where business_id = me.business_id and product_uid = v_uid;
      elsif v_img is not null then
        insert into cl_catalogue_images (business_id, product_uid, image_hash, data) values (me.business_id, v_uid, v_hash, v_img)
        on conflict (business_id, product_uid) do update set image_hash = excluded.image_hash, data = excluded.data;
      end if;
      out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'applied', 'seq', s,
        'overwrote', had and v_base is not null and cur.change_seq > v_base and cur.updated_by is distinct from me.id);
    exception when others then
      out_rows := out_rows || jsonb_build_object('uid', v_uid, 'status', 'refused', 'reason', 'BAD_ROW', 'message', left(sqlerrm, 120));
    end;
  end loop;
  return json_build_object('results', out_rows);
end $fn$;

create or replace function public.cl_branch_price_push(p_install_id text, p_secret_phrase text, p_device_key text, p_rows jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; caller_main boolean; r jsonb; out_rows jsonb := '[]'::jsonb; b cl_branches%rowtype;
        cur cl_branch_prices%rowtype; s bigint; v_uid text; v_op text; v_branch uuid; v_price numeric;
begin
  me := cl_catalogue_caller(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  caller_main := (select is_main from cl_branches where id = me.branch_id);
  if (case when jsonb_typeof(p_rows) = 'array' then jsonb_array_length(p_rows) not between 1 and 200 else true end) then
    raise exception 'Send between 1 and 200 prices at a time' using errcode = 'P0001';
  end if;
  perform 1 from cl_businesses where id = me.business_id for update;

  for r in select value from jsonb_array_elements(p_rows) loop
    v_uid := r->>'product_uid'; v_op := r->>'op_id';
    begin
      v_branch := (r->>'branch_id')::uuid;
      v_price := case when r->'price' is null or jsonb_typeof(r->'price') = 'null' then null else (r->>'price')::numeric end;
      if v_uid is null or v_op is null or v_op !~ '^[0-9a-f]{32}$' then
        out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'refused', 'reason', 'BAD_ROW'); continue;
      end if;
      select * into b from cl_branches where id = v_branch and business_id = me.business_id;
      if not found then
        out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'refused', 'reason', 'UNKNOWN_BRANCH'); continue;
      end if;
      if not caller_main and (b.id <> me.branch_id or b.price_mode <> 'branch_edits') then
        out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'refused', 'reason', 'NOT_ALLOWED'); continue;
      end if;
      if not exists (select 1 from cl_catalogue_products where business_id = me.business_id and product_uid = v_uid) then
        out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'refused', 'reason', 'UNKNOWN_PRODUCT'); continue;
      end if;
      select * into cur from cl_branch_prices where branch_id = v_branch and product_uid = v_uid for update;
      if found and cur.last_op_id = v_op then
        out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'duplicate', 'seq', cur.change_seq); continue;
      end if;
      s := nextval('cl_catalogue_seq');
      insert into cl_branch_prices (business_id, branch_id, product_uid, price, change_seq, last_op_id, updated_by, updated_ts)
      values (me.business_id, v_branch, v_uid, v_price, s, v_op, me.id, now())
      on conflict (branch_id, product_uid) do update set price = excluded.price, change_seq = excluded.change_seq,
        last_op_id = excluded.last_op_id, updated_by = excluded.updated_by, updated_ts = now();
      out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'applied', 'seq', s);
    exception when others then
      out_rows := out_rows || jsonb_build_object('product_uid', v_uid, 'branch_id', v_branch, 'status', 'refused', 'reason', 'BAD_ROW', 'message', left(sqlerrm, 120));
    end;
  end loop;
  return json_build_object('results', out_rows);
end $fn$;

create or replace function public.cl_device_customer_save(p_install_id text, p_secret_phrase text, p_device_key text, p_customer jsonb) returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; cur cl_customers%rowtype; dup cl_customers%rowtype; c cl_customers%rowtype;
        v_uid text := btrim(coalesce(p_customer->>'uid', '')); v_name text := btrim(coalesce(p_customer->>'name', ''));
        v_phone text := btrim(coalesce(p_customer->>'phone', '')); v_norm text; v_type text := coalesce(nullif(p_customer->>'customer_type', ''), 'retail');
        v_limit numeric;
begin
  me := cl_customer_till(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  perform 1 from cl_businesses where id = me.business_id for update;      -- one save at a time per business: phones stay unique, seq ordered
  if v_uid !~ '^[A-Za-z0-9-]{8,64}$' then raise exception 'A customer needs its uid' using errcode = 'P0001'; end if;
  if v_name = '' then raise exception 'A customer needs a name' using errcode = 'P0001'; end if;
  v_norm := cl_norm_phone(v_phone);
  if v_norm is null then raise exception 'A customer needs a valid phone number (e.g. 07x xxx xxxx)' using errcode = 'P0001'; end if;
  if v_type not in ('retail', 'wholesale') then raise exception 'Customer type is retail or wholesale' using errcode = 'P0001'; end if;
  v_limit := nullif(p_customer->>'credit_limit', '')::numeric;
  select * into dup from cl_customers where business_id = me.business_id and phone_norm = v_norm and customer_uid <> v_uid;
  if found then
    return json_build_object('ok', false, 'error', 'DUPLICATE_PHONE',
      'message', 'A customer with this phone already exists: ' || dup.name || '.', 'existing', cl_customer_json(dup));
  end if;
  select * into cur from cl_customers where business_id = me.business_id and customer_uid = v_uid for update;
  insert into cl_customers as x (business_id, customer_uid, name, phone, phone_norm, customer_type, credit_limit, address, national_id,
                                 active, change_seq, created_terminal, updated_terminal)
  values (me.business_id, v_uid, v_name, v_phone, v_norm, v_type, v_limit, nullif(btrim(coalesce(p_customer->>'address', '')), ''),
          nullif(btrim(coalesce(p_customer->>'national_id', '')), ''), coalesce((p_customer->>'active')::boolean, true),
          nextval('cl_customers_seq'), me.id, me.id)
  on conflict (business_id, customer_uid) do update set
    name = excluded.name, phone = excluded.phone, phone_norm = excluded.phone_norm, customer_type = excluded.customer_type,
    credit_limit = excluded.credit_limit, address = excluded.address, national_id = excluded.national_id, active = excluded.active,
    change_seq = excluded.change_seq, updated_terminal = excluded.updated_terminal, updated_at = now()
  returning * into c;
  return json_build_object('ok', true, 'customer', cl_customer_json(c), 'created', cur.customer_uid is null);
end $fn$;

create or replace function public.cl_terminal_set_active(
  p_install_id text, p_secret_phrase text, p_device_key text, p_terminal_id uuid, p_active boolean)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; me cl_terminals%rowtype; t cl_terminals%rowtype;
begin
  if p_active is null then raise exception 'Say whether the till is active' using errcode = 'P0001'; end if;
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  select tt.* into me from cl_terminals tt join cl_branches b on b.id = tt.branch_id
   where tt.vendor_id = v.id and tt.active and b.is_main;
  if not found then raise exception 'Only a main-branch terminal can change terminals' using errcode = 'P0001'; end if;
  select * into t from cl_terminals where id = p_terminal_id and business_id = me.business_id for update;
  if not found then raise exception 'Terminal not found in this business' using errcode = 'P0001'; end if;
  if t.id = me.id and not p_active then raise exception 'A till cannot deactivate itself' using errcode = 'P0001'; end if;
  if t.active is distinct from p_active then
    update cl_terminals set active = p_active where id = t.id;
    insert into cl_activity_log (staff_id, action, target_table, target_id, detail)
    values (null, case when p_active then 'terminal_reactivated' else 'terminal_deactivated' end, 'cl_terminals', t.id,
            jsonb_build_object('till_code', t.till_code, 'branch_id', t.branch_id, 'by_terminal', me.id, 'by_till', me.till_code));
  end if;
  return (cl_terminal_json(t.id)::jsonb || jsonb_build_object('active', p_active))::json;
end $fn$;

create or replace function public.cl_terminal_admin_set(
  p_install_id text, p_secret_phrase text, p_device_key text, p_terminal_id uuid,
  p_admin_salt text, p_admin_check text, p_admin_rounds integer)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; me cl_terminals%rowtype; t cl_terminals%rowtype;
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  select tt.* into me from cl_terminals tt join cl_branches b on b.id = tt.branch_id
   where tt.vendor_id = v.id and tt.active and b.is_main;
  if not found then raise exception 'Only a main-branch terminal can set a till''s Admin passcode' using errcode = 'P0001'; end if;
  if not cl_admin_seed_ok(p_admin_salt, p_admin_check, p_admin_rounds) then
    raise exception 'ADMIN_SEED_INVALID: That Admin passcode check value isn''t valid' using errcode = 'P0001';
  end if;
  select * into t from cl_terminals where id = p_terminal_id and business_id = me.business_id;
  if not found then raise exception 'Terminal not found in this business' using errcode = 'P0001'; end if;
  if t.id = me.id then raise exception 'A till sets its own Admin passcode in Settings' using errcode = 'P0001'; end if;
  insert into cl_terminal_admin_seeds (terminal_id, salt, check_value, rounds, set_by_terminal, created_ts, delivered_ts)
  values (t.id, p_admin_salt, p_admin_check, p_admin_rounds, me.id, now(), null)
  on conflict (terminal_id) do update set salt = excluded.salt, check_value = excluded.check_value, rounds = excluded.rounds,
    set_by_terminal = excluded.set_by_terminal, created_ts = excluded.created_ts, delivered_ts = null;
  insert into cl_activity_log (staff_id, action, target_table, target_id, detail)
  values (null, 'terminal_admin_set', 'cl_terminals', t.id,
          jsonb_build_object('till_code', t.till_code, 'branch_id', t.branch_id, 'by_terminal', me.id, 'by_till', me.till_code));
  return (cl_terminal_json(t.id)::jsonb || jsonb_build_object('admin_set', true))::json;
end $fn$;

create or replace function public.cl_branch_issue_join_code(
  p_install_id text, p_secret_phrase text, p_device_key text,
  p_branch_id uuid default null, p_new_branch_name text default null, p_valid_hours int default 24,
  p_admin_salt text default null, p_admin_check text default null, p_admin_rounds int default null)   -- admin passcode from main
returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; me cl_terminals%rowtype; target cl_branches%rowtype; code text; exp timestamptz;
        v_max integer;   -- Price plans (20261013120000)
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  -- admin passcode from main: a code without the new device's Admin check value comes from an older main build
  if not cl_admin_seed_ok(p_admin_salt, p_admin_check, p_admin_rounds) then
    raise exception 'UPDATE_MAIN_FIRST: This version of the app is too old to add terminals. Update this app, then try again.' using errcode = 'P0001';   -- clearer message (20261023180000)
  end if;
  select t.* into me from cl_terminals t join cl_branches b on b.id = t.branch_id
   where t.vendor_id = v.id and t.active and b.is_main;
  if not found then raise exception 'Only a main-branch terminal can add terminals' using errcode = 'P0001'; end if;

  if (p_branch_id is null) = (nullif(btrim(coalesce(p_new_branch_name,'')), '') is null) then
    raise exception 'Give either a branch or a new branch name';
  end if;
  -- Price plans (20261013120000): the business's plan may limit its branches (Lite: one).
  v_max := (cl_plan_version((select pl.plan_code from cl_plan_of(me.business_id, null) pl))).max_branches;
  if p_branch_id is not null then
    select * into target from cl_branches where id = p_branch_id and business_id = me.business_id;
    if not found then raise exception 'Branch not found in this business'; end if;
    if not target.is_main and not cl_plan_branch_allowed(target.id, v_max) then raise exception '%', cl_plan_branch_limit_text(v_max); end if;
  else
    select * into target from cl_branches where business_id = me.business_id and cl_branch_key(name) = cl_branch_key(p_new_branch_name);
    if found and not target.is_main and not cl_plan_branch_allowed(target.id, v_max) then raise exception '%', cl_plan_branch_limit_text(v_max); end if;
    if not found then
      if v_max is not null and (select count(*) from cl_branches cb where cb.business_id = me.business_id) >= v_max then
        raise exception '%', cl_plan_branch_limit_text(v_max);
      end if;
      insert into cl_branches (business_id, name, is_main) values (me.business_id, btrim(p_new_branch_name), false)
      returning * into target;
    end if;
  end if;

  exp := now() + make_interval(hours => greatest(1, least(coalesce(p_valid_hours, 24), 72)));
  loop
    code := cl_new_join_code();
    begin
      insert into cl_branch_join_codes (branch_id, code_hash, issued_by_terminal, expires_ts,
                                        admin_salt, admin_check, admin_rounds)                  -- admin passcode from main
      values (target.id, encode(extensions.digest(code, 'sha256'), 'hex'), me.id, exp,
              p_admin_salt, p_admin_check, p_admin_rounds);
      exit;
    exception when unique_violation then -- astronomically rare: draw again
    end;
  end loop;
  return json_build_object('code', substr(code,1,4) || '-' || substr(code,5,4),
    'branch_id', target.id, 'branch_name', target.name, 'expires_ts', exp);
end $fn$;

create or replace function public.cl_branch_set_price_mode(p_install_id text, p_secret_phrase text, p_device_key text,
                                                p_branch_id uuid, p_mode text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; s bigint;
begin
  me := cl_catalogue_caller(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  if not (select is_main from cl_branches where id = me.branch_id) then return json_build_object('error', 'NOT_MAIN'); end if;
  if p_mode is null or p_mode not in ('follow_main', 'main_sets', 'branch_edits') then
    raise exception 'Unknown price policy' using errcode = 'P0001';
  end if;
  perform 1 from cl_businesses where id = me.business_id for update;
  if not exists (select 1 from cl_branches where id = p_branch_id and business_id = me.business_id) then
    return json_build_object('error', 'UNKNOWN_BRANCH');
  end if;
  if (select price_mode from cl_branches where id = p_branch_id) = p_mode then
    return json_build_object('branch_id', p_branch_id, 'price_mode', p_mode, 'unchanged', true);
  end if;
  s := nextval('cl_catalogue_seq');
  update cl_branches set price_mode = p_mode, price_mode_seq = s where id = p_branch_id;
  return json_build_object('branch_id', p_branch_id, 'price_mode', p_mode, 'seq', s);
end $fn$;

create or replace function public.cl_branch_set_business_day(p_install_id text, p_secret_phrase text, p_device_key text,
                                                  p_branch_id uuid, p_hours integer)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype;
begin
  me := cl_catalogue_caller(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  -- coalesce: a missing or null is_main is "not main" (fails closed; is_main is not null today)
  if not coalesce((select is_main from cl_branches where id = me.branch_id), false) then return json_build_object('error', 'NOT_MAIN'); end if;
  if p_hours is not null and p_hours not between 0 and 6 then
    raise exception 'The business day can end from 00:00 to 06:00' using errcode = 'P0001';
  end if;
  perform 1 from cl_businesses where id = me.business_id for update;
  if not exists (select 1 from cl_branches where id = p_branch_id and business_id = me.business_id) then
    return json_build_object('error', 'UNKNOWN_BRANCH');
  end if;
  if (select business_day_cutoff from cl_branches where id = p_branch_id) is not distinct from p_hours then
    return json_build_object('branch_id', p_branch_id, 'business_day_cutoff', p_hours, 'unchanged', true);
  end if;
  update cl_branches set business_day_cutoff = p_hours where id = p_branch_id;
  return json_build_object('branch_id', p_branch_id, 'business_day_cutoff', p_hours);
end $fn$;

create or replace function public.cl_device_pack_submit(p_install_id text, p_secret_phrase text, p_device_key text,
                                             p_pack_uid uuid, p_header text, p_header_sha256 text) returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; r jsonb;
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  r := cl_market_pack_open(p_pack_uid, v, cl_market_check_header(p_header, p_header_sha256, p_install_id), 'app', null);
  perform cl_market_purge_photos();   -- the packs this one replaced, and any left undecided over 14 days
  return r::json;
end $fn$;

create or replace function public.cl_stock_sale(p_install_id text, p_secret_phrase text, p_device_key text, p_sale_uid text, p_lines jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare me cl_terminals%rowtype; b cl_branches%rowtype; r record; refused jsonb := '[]'::jsonb; out_lines jsonb := '[]'::jsonb;
        t record; prods text[]; have integer;
begin
  me := cl_catalogue_caller(p_install_id, p_secret_phrase, p_device_key);
  if not me.active then return json_build_object('error', 'TERMINAL_INACTIVE'); end if;
  select * into b from cl_branches where id = me.branch_id;
  if b.stock_mode <> 'shared' then return json_build_object('error', 'NOT_SHARED'); end if;
  if p_sale_uid is null or p_sale_uid !~ '^[0-9a-f]{32}$' then raise exception 'A sale needs its uid' using errcode = 'P0001'; end if;
  if (case when jsonb_typeof(p_lines) = 'array' then jsonb_array_length(p_lines) not between 1 and 500 else true end) then
    raise exception 'Send between 1 and 500 lines' using errcode = 'P0001';
  end if;
  perform 1 from cl_businesses where id = me.business_id for update;
  -- a retried request (e.g. after a timeout): the first answer, nothing changes
  if exists (select 1 from cl_stock_events where ref_uid = 'sale:'||p_sale_uid) then
    select coalesce(jsonb_agg(jsonb_build_object('product_uid', product_uid, 'from_available', from_available, 'from_allowance', from_allowance)), '[]'::jsonb)
      into out_lines from cl_stock_events where ref_uid = 'sale:'||p_sale_uid and kind in ('sale', 'offline_sale');
    select array_agg(product_uid) into prods from cl_stock_events where ref_uid = 'sale:'||p_sale_uid;
    return json_build_object('ok', true, 'already', true, 'lines', out_lines, 'stock', cl_stock_rows(me, prods, null));
  end if;
  -- check every line first (rows locked in product order)
  for r in select x.p, sum(x.q)::int q from (select value->>'product_uid' p, (value->>'qty')::int q from jsonb_array_elements(p_lines)) x
            group by x.p order by x.p loop
    if r.q is null or r.q <= 0 then raise exception 'Quantities must be whole numbers above zero' using errcode = 'P0001'; end if;
    select coalesce((select available from cl_branch_stock where branch_id = b.id and product_uid = r.p for update), 0)
         + coalesce((select qty from cl_till_allowance where terminal_id = me.id and product_uid = r.p for update), 0) into have;
    if have < r.q then refused := refused || jsonb_build_object('product_uid', r.p, 'left', have, 'wanted', r.q); end if;
  end loop;
  if jsonb_array_length(refused) > 0 then return json_build_object('ok', false, 'refused', refused); end if;
  for r in select x.p, sum(x.q)::int q from (select value->>'product_uid' p, (value->>'qty')::int q from jsonb_array_elements(p_lines)) x
            group by x.p order by x.p loop
    select * into t from cl_stock_take(b.id, r.p, me.id, r.q, false);
    perform cl_stock_event('sale:'||p_sale_uid||':'||r.p, 'sale:'||p_sale_uid, me.business_id, b.id, me.id, r.p, 'sale',
                           -r.q, t.from_available, t.from_allowance, '{}'::jsonb);
    out_lines := out_lines || jsonb_build_object('product_uid', r.p, 'from_available', t.from_available, 'from_allowance', t.from_allowance);
    prods := array_append(prods, r.p);
  end loop;
  perform cl_stock_rebalance(me, prods);
  perform cl_stock_check(b.id);
  return json_build_object('ok', true, 'lines', out_lines, 'stock', cl_stock_rows(me, prods, null));
end $fn$;

create or replace function public.cl_device_itred_order_complete(p_install_id text, p_secret_phrase text, p_device_key text,
                                                      p_uid uuid, p_order_id uuid) returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; v_itred uuid; po purchase_orders%rowtype;
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  v_itred := itred_vendor_of_device(v);
  if v_itred is null then return json_build_object('error', 'NOT_ON_ITRED'); end if;
  if p_uid is null then return json_build_object('error', 'UID_REQUIRED'); end if;
  if exists (select 1 from itred_po_updates where uid = p_uid) then return json_build_object('ok', true, 'duplicate', true); end if;
  select * into po from purchase_orders where id = p_order_id;
  if po.id is null or po.vendor_id is distinct from v_itred then return json_build_object('error', 'NOT_FOUND'); end if;
  insert into itred_po_updates (uid, purchase_order_id, kind, vendor_id, till_code)
  values (p_uid, po.id, 'complete', v.id, (select t.till_code from cl_terminals t where t.install_id = v.install_id));
  update purchase_orders set completed_at = coalesce(completed_at, now()) where id = po.id;
  return json_build_object('ok', true, 'order', itred_order_json(po.id));
end $fn$;

create or replace function public.cl_device_itred_line_update(p_install_id text, p_secret_phrase text, p_device_key text,
                                                   p_uid uuid, p_item_id uuid, p_qty_fulfilled numeric, p_note text default null) returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; v_itred uuid; i purchase_order_items%rowtype; po purchase_orders%rowtype; v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  v_itred := itred_vendor_of_device(v);
  if v_itred is null then return json_build_object('error', 'NOT_ON_ITRED'); end if;
  if p_uid is null then return json_build_object('error', 'UID_REQUIRED'); end if;
  if exists (select 1 from itred_po_updates where uid = p_uid) then return json_build_object('ok', true, 'duplicate', true); end if;
  select * into i from purchase_order_items where id = p_item_id;
  select * into po from purchase_orders where id = i.purchase_order_id;
  if i.id is null or po.vendor_id is distinct from v_itred then return json_build_object('error', 'NOT_FOUND'); end if;
  if po.status = 'closed' then return json_build_object('error', 'CLOSED', 'message', 'The customer closed this order.'); end if;
  if p_qty_fulfilled is null or p_qty_fulfilled < 0 or p_qty_fulfilled > i.quantity_requested then
    return json_build_object('error', 'BAD_QTY', 'message', 'Fulfilled must be 0 to ' || i.quantity_requested::text || '.');
  end if;
  if v_note is not null and length(v_note) > 300 then return json_build_object('error', 'NOTE_TOO_LONG'); end if;
  insert into itred_po_updates (uid, purchase_order_id, item_id, kind, qty_fulfilled, note, vendor_id, till_code)
  values (p_uid, po.id, i.id, 'line', p_qty_fulfilled, v_note, v.id, (select t.till_code from cl_terminals t where t.install_id = v.install_id));
  update purchase_order_items set quantity_fulfilled = p_qty_fulfilled, vendor_note = v_note, vendor_updated_at = now(),
         customer_confirmed_at = case when quantity_fulfilled = p_qty_fulfilled then customer_confirmed_at end,   -- a changed quantity needs a new confirmation
         customer_dispute = case when quantity_fulfilled = p_qty_fulfilled then customer_dispute end
   where id = i.id;
  return json_build_object('ok', true, 'order', itred_order_json(po.id));
end $fn$;

create or replace function public.cl_device_itred_message_send(p_install_id text, p_secret_phrase text, p_device_key text,
                                                    p_id uuid, p_order_id uuid, p_body text) returns json
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype; v_itred uuid; v_body text := btrim(coalesce(p_body, ''));
begin
  v := cl_install_vendor(p_install_id, p_secret_phrase, p_device_key, false);
  v_itred := itred_vendor_of_device(v);
  if v_itred is null then return json_build_object('error', 'NOT_ON_ITRED'); end if;
  if p_id is null then return json_build_object('error', 'UID_REQUIRED'); end if;
  if exists (select 1 from itred_order_messages where id = p_id) then return json_build_object('ok', true, 'duplicate', true); end if;
  if not exists (select 1 from purchase_orders where id = p_order_id and vendor_id = v_itred) then return json_build_object('error', 'NOT_FOUND'); end if;
  if length(v_body) not between 1 and 1000 then return json_build_object('error', 'BAD_BODY', 'message', 'Write 1 to 1000 characters.'); end if;
  insert into itred_order_messages (id, purchase_order_id, author, body, vendor_id, till_code, vendor_read_at)
  values (p_id, p_order_id, 'vendor', v_body, v.id, (select t.till_code from cl_terminals t where t.install_id = v.install_id), now());
  update itred_order_messages set vendor_read_at = now() where purchase_order_id = p_order_id and author = 'customer' and vendor_read_at is null;
  return json_build_object('ok', true);
end $fn$;

